// Deterministic size export only. Character artwork is generated by image_gen.
// node export.mjs source.png /absolute/path/to/node_modules/sharp
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import fs from 'node:fs/promises';

const require = createRequire(import.meta.url);
const sharp = require(process.argv[3] || 'sharp');
const input = process.argv[2];
if (!input) throw new Error('Pass the image_gen source PNG path.');
const output = path.dirname(fileURLToPath(import.meta.url));
const metadata = await sharp(input).metadata();
if (!metadata.hasAlpha) throw new Error('Expected a transparent source PNG.');
const { data, info } = await sharp(input).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
let left = info.width, top = info.height, right = -1, bottom = -1, transparent = 0;
for (let y = 0; y < info.height; y++) {
  for (let x = 0; x < info.width; x++) {
    const alpha = data[(y * info.width + x) * info.channels + 3];
    if (alpha === 0) transparent++;
    if (alpha > 8) {
      left = Math.min(left, x); top = Math.min(top, y);
      right = Math.max(right, x); bottom = Math.max(bottom, y);
    }
  }
}
if (right < left || transparent === 0) throw new Error('Source must have visible art and transparent background.');
left = Math.max(0, left - 1); top = Math.max(0, top - 1);
right = Math.min(info.width - 1, right + 1); bottom = Math.min(info.height - 1, bottom + 1);
const bounds = { left, top, width: right - left + 1, height: bottom - top + 1 };
const resized = await sharp(input).extract(bounds)
  .resize({ width: 60, height: 60, fit: 'inside', kernel: 'lanczos3' })
  .png().toBuffer({ resolveWithObject: true });
const offsetX = Math.floor((64 - resized.info.width) / 2);
const offsetY = 62 - resized.info.height;
const sprite = path.join(output, 'collector-64.png');
await sharp({ create: { width: 64, height: 64, channels: 4, background: '#00000000' } })
  .composite([{ input: resized.data, left: offsetX, top: offsetY }]).png().toFile(sprite);
// Nearest enlargement exposes the actual exported pixels; no new detail is added.
await sharp(sprite).resize(384, 384, { kernel: 'nearest' })
  .png().toFile(path.join(output, 'collector-64-inspect-6x.png'));
await fs.copyFile(input, path.join(output, 'source-transparent.png'));
const final = await sharp(sprite).metadata();
if (final.width !== 64 || final.height !== 64 || !final.hasAlpha) throw new Error('64px alpha export validation failed.');
const record = { source: input, sourceSize: [info.width, info.height], alphaBounds: bounds,
  exportSize: [64, 64], contentSize: [resized.info.width, resized.info.height],
  offset: [offsetX, offsetY], hasAlpha: final.hasAlpha,
  sourceTransparentPixelRatio: transparent / (info.width * info.height),
  resizeKernel: 'lanczos3', inspectionScale: 6, inspectionKernel: 'nearest',
  status: 'single-frame held-brush review only; not integrated or animation-ready' };
console.log(JSON.stringify(record, null, 2));
